// Builds blog/<slug>.html for every blog/posts/<slug>.md and lists them on blog/index.html.
// The .md files are committed by the Content Engine (Make scenario) on the day each post is due;
// .github/workflows/blog.yml runs this and commits the result. Page shell = blog/hello.html.
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { marked } from "marked";

const BLOG = join(import.meta.dirname, "..", "..", "blog");
const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const longDate = (d) => { const [y, m, day] = d.split("-").map(Number); return `${day} ${MONTHS[m - 1]} ${y}`; };

function parse(raw) {
  const m = raw.replace(/\r\n/g, "\n").match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/);
  const meta = {};
  for (const line of (m ? m[1] : "").split("\n")) {
    const f = line.match(/^(\w+):\s*(.*)$/);
    if (f) meta[f[1]] = f[2].trim();
  }
  // The body starts with its own "slug:" / "summary:" lines before the first blank line.
  let body = (m ? m[2] : raw).replace(/^\n+/, "");
  const head = body.match(/^((?:\w+:.*\n)+)\n/);
  if (head) {
    for (const line of head[1].split("\n")) {
      const f = line.match(/^(\w+):\s*(.*)$/);
      if (f && !meta[f[1]]) meta[f[1]] = f[2].trim();
    }
    body = body.slice(head[0].length);
  }
  return { ...meta, body };
}

const shell = readFileSync(join(BLOG, "hello.html"), "utf8");
const posts = readdirSync(join(BLOG, "posts"))
  .filter((f) => f.endsWith(".md"))
  .map((f) => parse(readFileSync(join(BLOG, "posts", f), "utf8")))
  .filter((p) => p.slug && p.date && p.title)
  .sort((a, b) => b.date.localeCompare(a.date));

for (const p of posts) {
  const cover = p.cover ? `<img src="${esc(p.cover)}" alt="${esc(p.cover_alt || "")}" width="1080" height="1350" loading="eager">\n        ` : "";
  const html = shell
    .replace(/<title>[^<]*<\/title>/, `<title>${esc(p.title)} · Nina Niamh</title>`)
    .replace(/<meta name="description" content="[^"]*">/, `<meta name="description" content="${esc(p.summary || p.title)}">`)
    .replace(/\s*<!-- DRAFT[^>]*-->/, "")
    .replace(/<time datetime="[^"]*">[^<]*<\/time>/, `<time datetime="${p.date}">${longDate(p.date)}</time>`)
    .replace(/<h1>[\s\S]*?<\/h1>/, `<h1>${esc(p.title)}</h1>`)
    .replace(/<p class="lede">[\s\S]*?<\/p>/, `<p class="lede">${esc(p.summary || "")}</p>`)
    .replace(/<div class="post-body">[\s\S]*?<\/div>(\s*<div class="post-end">)/, `<div class="post-body">\n        ${cover}${marked.parse(p.body).trim()}\n      </div>$1`);
  writeFileSync(join(BLOG, `${p.slug}.html`), html);
}

const cards = posts
  .map((p) => `      <li>
        <a class="post-card" href="${p.slug}.html">
          <time datetime="${p.date}">${longDate(p.date)}</time>
          <h2>${esc(p.title)}</h2>
          <p>${esc(p.summary || "")}</p>
          <span class="card-foot">Read the post <span class="go"><svg class="ico" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg></span></span>
        </a>
      </li>`)
  .join("\n");
const indexPath = join(BLOG, "index.html");
const index = readFileSync(indexPath, "utf8");
const START = "<!-- posts:start (generated by .github/scripts/build-blog.mjs) -->";
const END = "<!-- posts:end -->";
const from = index.indexOf(START);
const to = index.indexOf(END, from);
if (from < 0 || to < 0) throw new Error("blog/index.html is missing the posts:start / posts:end markers");
writeFileSync(indexPath, `${index.slice(0, from + START.length)}\n${cards}\n      ${index.slice(to)}`);
console.log(`build-blog: ${posts.length} posts`);
